{"metadata":{"kernelspec":{"language":"python","display_name":"Python 3","name":"python3"},"language_info":{"name":"python","version":"3.12.13","mimetype":"text/x-python","codemirror_mode":{"name":"ipython","version":3},"pygments_lexer":"ipython3","nbconvert_exporter":"python","file_extension":".py"},"kaggle":{"accelerator":"none","dataSources":[],"dockerImageVersionId":28755,"isInternetEnabled":false,"language":"python","sourceType":"notebook","isGpuEnabled":false}},"nbformat_minor":4,"nbformat":4,"cells":[{"cell_type":"code","source":"# %% [code] {\"execution\":{\"iopub.status.busy\":\"2026-08-25T08:03:08.477120Z\",\"iopub.execute_input\":\"2026-08-25T08:03:08.477658Z\",\"iopub.status.idle\":\"2026-08-25T08:03:08.490308Z\",\"shell.execute_reply.started\":\"2026-08-25T08:03:08.477629Z\",\"shell.execute_reply\":\"2026-08-25T08:03:08.489492Z\"}}\n%%writefile experimento_fase2.py\n\"\"\"\n==============================================================================\n# COPYRIGHT & INTELLECTUAL PROPERTY NOTICE\n# Copyright (c) 2026 Eduardo Ayala Tovar\n# Title: EXP06 — Beatriz Fire Test_fase2.py\n# License: PolyForm Noncommercial License 1.0.0\n==============================================================================\n\"\"\"\nimport os\nimport gc\nimport json\nimport math\nimport time\nimport random\nimport hashlib\nfrom enum import Enum\nfrom dataclasses import dataclass\nfrom typing import Dict, Any, Optional, List, Tuple\nimport numpy as np\nimport torch\nimport torch.nn.functional as F\nfrom transformers import AutoTokenizer, AutoModelForCausalLM\n\n# ==============================================================================\n# CONFIGURACIÓN DEL EXPERIMENTO (EXP06 - FASE 2)\n# ==============================================================================\nAUTHOR = \"Eduardo Ayala Tovar\"\nLICENSE = \"PolyForm Noncommercial License 1.0.0\"\nEXPERIMENT = \"EXP06 — Beatriz Fire Test_fase2.py\"\nSEEDS = [11, 22, 33]\nEPOCHS = 8\nDRAWS_PER_EPOCH = 60\n\n# Agenda de corrupción de la IA maestra (Texto abierto alucinante/falso)\nP_LIE_SCHEDULE = [0.50, 0.50, 0.50, 0.50, 0.55, 0.60, 0.65, 0.70]\nP_UNKNOWN, P_INVALID = 0.10, 0.05  \n\n# Parámetros operativos de la fórmula de contraste adaptada a texto libre\nALPHA, BETA, MARGIN = 0.5, 1.0, 0.5  \nLR, MAX_LENGTH, GRAD_CLIP = 5e-5, 64, 1.0\n\nOUTPUT_DIR = \"/kaggle/working/exp06_beatriz_open_semantic\"\nFINAL_FILE = os.path.join(OUTPUT_DIR, \"exp06_open_results.json\")\nos.makedirs(OUTPUT_DIR, exist_ok=True)\nDEVICE = torch.device(\"cuda\" if torch.cuda.is_available() else \"cpu\")\n\n# ==============================================================================\n# CORPUS ANCLA SEMÁNTICO ABIERTO (Hechos de Referencia en Texto Libre)\n# ==============================================================================\nANCHOR_CORPUS = {\n    \"ibuprofen function\": {\n        \"true_text\": \"Ibuprofen is a nonsteroidal anti-inflammatory drug that is processed via the kidneys.\",\n        \"false_text\": \"Ibuprofen is a steroid painkiller drug that is processed via the liver.\",\n        \"keywords\": [\"ibuprofen\", \"kidneys\", \"nonsteroidal\"]\n    },\n    \"paris capital\": {\n        \"true_text\": \"Paris is the official capital city of France, located on the Seine river.\",\n        \"false_text\": \"Paris is the official capital city of Germany, located on the Rhine river.\",\n        \"keywords\": [\"paris\", \"france\", \"capital\"]\n    },\n    \"water freezing\": {\n        \"true_text\": \"Pure water freezes precisely at zero degrees Celsius under standard atmospheric pressure.\",\n        \"false_text\": \"Pure water freezes precisely at one hundred degrees Celsius under standard conditions.\",\n        \"keywords\": [\"water\", \"freezes\", \"zero\"]\n    },\n    \"photosynthesis process\": {\n        \"true_text\": \"Plants use chlorophyll to absorb light and convert carbon dioxide into oxygen.\",\n        \"false_text\": \"Plants use hemoglobin to absorb light and convert oxygen into carbon dioxide.\",\n        \"keywords\": [\"plants\", \"chlorophyll\", \"oxygen\"]\n    },\n    \"bitcoin consensus\": {\n        \"true_text\": \"Bitcoin secures its network transactions using a decentralized proof of work algorithm.\",\n        \"false_text\": \"Bitcoin secures its network transactions using a centralized authority server mesh.\",\n        \"keywords\": [\"bitcoin\", \"proof\", \"decentralized\"]\n    },\n    \"dna structure\": {\n        \"true_text\": \"The DNA molecule features a double helix shape composed of base nucleotide pairs.\",\n        \"false_text\": \"The DNA molecule features a single strand structure composed of amino acid chains.\",\n        \"keywords\": [\"dna\", \"helix\", \"double\"]\n    }\n}\n\n\n# %% [code] {\"execution\":{\"iopub.status.busy\":\"2026-08-25T08:03:08.491869Z\",\"iopub.execute_input\":\"2026-08-25T08:03:08.492218Z\",\"iopub.status.idle\":\"2026-08-25T08:03:08.509640Z\",\"shell.execute_reply.started\":\"2026-08-25T08:03:08.492192Z\",\"shell.execute_reply\":\"2026-08-25T08:03:08.508878Z\"}}\n%%writefile -a experimento_fase2.py\n\nUNKNOWN_POOL = [\n    {\"true_text\": \"Silver is a highly conductive precious metal.\", \"false_text\": \"Silver is a liquid element at room temperature.\"},\n    {\"true_text\": \"A star is a massive luminous sphere of plasma.\", \"false_text\": \"A star is a solid rocky body orbiting a planet.\"}\n]\n\nTRANSFER_TEST = [\n    {\n        \"prompt\": \"Explain the clearance of ibuprofen:\",\n        \"truth\": \"It clears through renal filtration in the kidneys.\",\n        \"lie\": \"It clears through hepatic metabolism in the liver.\"\n    },\n    {\n        \"prompt\": \"What is the structure of DNA?\",\n        \"truth\": \"It presents a classic double helix molecular geometry.\",\n        \"lie\": \"It presents a long single strand peptide chain.\"\n    }\n]\n\nNEUTRAL_EVAL_TEXTS = [\n    \"The sky looks clear today.\", \"Reading books expands your general knowledge.\",\n    \"A computer executes binary instructions.\", \"Cooking food requires thermal energy transfers.\"\n]\n\nclass Verdict(str, Enum):\n    VERIFIED = \"VERIFIED\"\n    CONTRADICTED = \"CONTRADICTED\"\n    UNKNOWN = \"UNKNOWN\"\n    INVALID = \"INVALID\"\n\nclass OpenFilterGate:\n    def __init__(self, anchor_corpus, policy):\n        self.policy = policy\n        self.corpus = anchor_corpus\n\n    def decide(self, generated_text: str) -> Dict[str, Any]:\n        if not generated_text or len(generated_text.strip()) < 5:\n            return {\"verdict\": Verdict.INVALID.value, \"true_text\": None, \"false_text\": None}\n        \n        if self.policy == \"none\":\n            return {\"verdict\": Verdict.VERIFIED.value, \"true_text\": generated_text, \"false_text\": None}\n\n        matched_key = None\n        text_lower = generated_text.lower()\n        \n        for key, data in self.corpus.items():\n            if any(kw in text_lower for kw in data[\"keywords\"]):\n                matched_key = key\n                break\n        \n        if not matched_key:\n            return {\"verdict\": Verdict.UNKNOWN.value, \"true_text\": None, \"false_text\": generated_text}\n        \n        data = self.corpus[matched_key]\n        \n        def calc_overlap(t1, t2):\n            w1 = set(t1.lower().replace(\".\", \"\").split())\n            w2 = set(t2.lower().replace(\".\", \"\").split())\n            return len(w1.intersection(w2))\n        \n        score_truth = calc_overlap(generated_text, data[\"true_text\"])\n        score_lie = calc_overlap(generated_text, data[\"false_text\"])\n        \n        if score_lie > score_truth:\n            return {\"verdict\": Verdict.CONTRADICTED.value, \"true_text\": data[\"true_text\"], \"false_text\": generated_text}\n        \n        return {\"verdict\": Verdict.VERIFIED.value, \"true_text\": data[\"true_text\"], \"false_text\": None}\n\ndef generator_A_open(rng, p_lie) -> str:\n    draw = rng.random()\n    if draw < P_INVALID: return \"N/A structural error...\"\n    if draw < P_INVALID + P_UNKNOWN:\n        sample = rng.choice(UNKNOWN_POOL)\n        return sample[\"false_text\"] if rng.random() < p_lie else sample[\"true_text\"]\n    \n    key = rng.choice(list(ANCHOR_CORPUS.keys()))\n    data = ANCHOR_CORPUS[key]\n    if rng.random() < p_lie: return data[\"false_text\"]\n    return data[\"true_text\"]\n\ndef sha256_file(path):\n    hasher = hashlib.sha256()\n    with open(path, \"rb\") as file:\n        for chunk in iter(lambda: file.read(1024 * 1024), b\"\"): hasher.update(chunk)\n    return hasher.hexdigest()\n\ndef canonical_model_hash(model):\n    hasher = hashlib.sha256()\n    state = model.state_dict()\n    for name in sorted(state.keys()):\n        tensor = state[name].detach().cpu().contiguous()\n        hasher.update(name.encode(\"utf-8\"))\n        hasher.update(tensor.numpy().tobytes(order=\"C\"))\n    return hasher.hexdigest()\n\ndef set_global_determinism(seed):\n    random.seed(seed); np.random.seed(seed); torch.manual_seed(seed)\n    if torch.cuda.is_available(): torch.cuda.manual_seed_all(seed)\n\ndef clear_memory():\n    gc.collect()\n    if torch.cuda.is_available(): torch.cuda.empty_cache()\n\n\n# %% [code] {\"execution\":{\"iopub.status.busy\":\"2026-08-25T08:03:08.511713Z\",\"iopub.execute_input\":\"2026-08-25T08:03:08.512060Z\",\"iopub.status.idle\":\"2026-08-25T08:03:08.530519Z\",\"shell.execute_reply.started\":\"2026-08-25T08:03:08.512025Z\",\"shell.execute_reply\":\"2026-08-25T08:03:08.529672Z\"}}\n%%writefile -a experimento_fase2.py\n\ndef make_sequence_batch(text):\n    encoded = tokenizer(text, return_tensors=\"pt\", add_special_tokens=False, truncation=True, max_length=MAX_LENGTH)\n    labels = encoded[\"input_ids\"].clone()\n    batch = {k: v.to(DEVICE) for k, v in encoded.items()}\n    batch[\"labels\"] = labels.to(DEVICE)\n    return batch\n\ndef extract_sequence_logprob(logits, labels):\n    shift_logits = logits[:, :-1, :].contiguous()\n    shift_labels = labels[:, 1:].contiguous()\n    log_probs = F.log_softmax(shift_logits, dim=-1)\n    return torch.gather(log_probs, dim=-1, index=shift_labels.unsqueeze(-1)).squeeze(-1).mean()\n\n@torch.no_grad()\ndef open_continuation_score(model, prompt, continuation):\n    model.eval()\n    full_ids = tokenizer(prompt + \" \" + continuation, return_tensors=\"pt\", add_special_tokens=False)[\"input_ids\"].to(DEVICE)\n    logits = model(input_ids=full_ids).logits[:, :-1, :]\n    labels = full_ids[:, 1:]\n    return float(torch.gather(F.log_softmax(logits, dim=-1), dim=-1, index=labels.unsqueeze(-1)).squeeze(-1)[:, -1:].mean().cpu().item())\n\ndef evaluate_open_transfer(model, test_cases):\n    margins = []\n    for case in test_cases:\n        p, t, l = case[\"prompt\"], case[\"truth\"], case[\"lie\"]\n        margins.append(open_continuation_score(model, p, t) - open_continuation_score(model, p, l))\n    return float(np.mean(margins))\n\ndef train_branch_open(policy, seed):\n    set_global_determinism(seed)\n    model = AutoModelForCausalLM.from_pretrained(MODEL_PATH, local_files_only=True).to(DEVICE)\n    optimizer = torch.optim.AdamW(model.parameters(), lr=LR)\n    gate = OpenFilterGate(ANCHOR_CORPUS, policy)\n    rng = random.Random(seed)\n    b_updates, history = 0, []\n\n    contamination_suite = [{\"prompt\": \"Fact verification output:\", \"truth\": d[\"true_text\"], \"lie\": d[\"false_text\"]} for d in ANCHOR_CORPUS.values()]\n\n    for epoch in range(EPOCHS):\n        p_lie = P_LIE_SCHEDULE[epoch]\n        epoch_losses = []\n        chunk = [generator_A_open(rng, p_lie) for _ in range(DRAWS_PER_EPOCH)]\n        \n        for raw_text in chunk:\n            decision = gate.decide(raw_text)\n            verdict, true_txt, false_txt = decision[\"verdict\"], decision[\"true_text\"], decision[\"false_text\"]\n            if true_txt is None: continue \n\n            optimizer.zero_grad(set_to_none=True)\n            model.train()\n            \n            true_batch = make_sequence_batch(true_txt)\n            t_logits = model(**true_batch).logits\n            ce_loss = F.cross_entropy(\n                t_logits[:, :-1, :].contiguous().view(-1, t_logits.size(-1)), \n                true_batch[\"labels\"][:, 1:].contiguous().view(-1)\n            )\n            l_ce_total = ALPHA * ce_loss\n            l_verdad_total = torch.tensor(0.0, device=DEVICE)\n            \n            if policy == \"beatriz\" and verdict == Verdict.CONTRADICTED.value and false_txt is not None:\n                false_batch = make_sequence_batch(false_txt)\n                f_logits = model(**false_batch).logits\n                truth_logp = extract_sequence_logprob(t_logits, true_batch[\"labels\"])\n                false_logp = extract_sequence_logprob(f_logits, false_batch[\"labels\"])\n                l_verdad_total = BETA * F.softplus(MARGIN + false_logp - truth_logp)\n\n            loss = l_ce_total + l_verdad_total\n            loss.backward()\n            torch.nn.utils.clip_grad_norm_(model.parameters(), GRAD_CLIP)\n            optimizer.step()\n            b_updates += 1\n            epoch_losses.append(float(loss.detach().cpu().item()))\n\n        tm = evaluate_open_transfer(model, contamination_suite)\n        history.append({\"epoch\": epoch + 1, \"mean_loss\": float(np.mean(epoch_losses)), \"truth_margin\": tm})\n        print(f\"Semilla {seed} | {policy.upper()} | Época {epoch+1}/8 | Pérdida: {history[-1]['mean_loss']:.4f} | Margen Semántico: {tm:.2f}\")\n\n    final_hash = canonical_model_hash(model)\n    neutral_lp = float(np.mean([open_continuation_score(model, t, \"\") for t in NEUTRAL_EVAL_TEXTS]))\n    transfer_m = evaluate_open_transfer(model, TRANSFER_TEST)\n    del optimizer, model\n    clear_memory()\n    return {\"b_updates\": b_updates, \"history\": history, \"model_hash\": final_hash, \"neutral_logprob\": neutral_lp, \"transfer_margin\": transfer_m}\n\nprint(\"=\"*80 + \"\\nINICIANDO PIPELINE DE FASE 2: TEXTO ABIERTO SEMÁNTICO EN KAGGLE\\n\" + \"=\"*80)\nprint(f\"Propietario Intelectual: {AUTHOR}\\nLicencia legal: {LICENSE}\\n\")\n\nMODEL_PATH = \"/kaggle/input/datasets/rahulbhat44/gpt-2-offline-model-and-tokenizer-for-kaggle/gpt2_model/gpt2_model\"\nTOKENIZER_PATH = \"/kaggle/input/datasets/rahulbhat44/gpt-2-offline-model-and-tokenizer-for-kaggle/gpt2_tokenizer/gpt2_tokenizer\"\n\ntokenizer = AutoTokenizer.from_pretrained(TOKENIZER_PATH, local_files_only=True, use_fast=True)\nif tokenizer.pad_token is None: tokenizer.pad_token = tokenizer.eos_token\n\nresults = {}\nfor seed in SEEDS:\n    print(f\"\\n>>> PROCESANDO SEMILLA CRIPTOGRÁFICA: {seed} <<<\")\n    results[f\"seed_{seed}\"] = {\"NONE\": train_branch_open(\"none\", seed), \"BEATRIZ\": train_branch_open(\"beatriz\", seed)}\n\nwith open(FINAL_FILE, \"w\") as f: \n    json.dump({\"experiment\": EXPERIMENT, \"copyright\": f\"Copyright (c) 2026 {AUTHOR}\", \"license\": LICENSE, \"results\": results}, f, indent=2)\n\nprint(\"\\n\" + \"=\"*80 + f\"\\nFASE 2 TERMINADA | REPORTE EN: {FINAL_FILE}\\nSHA256: \" + sha256_file(FINAL_FILE) + \"\\n\" + \"=\"*80)\n\n\n# %% [code] {\"execution\":{\"iopub.status.busy\":\"2026-08-25T08:03:08.531726Z\",\"iopub.execute_input\":\"2026-08-25T08:03:08.532099Z\",\"iopub.status.idle\":\"2026-08-25T08:08:24.220184Z\",\"shell.execute_reply.started\":\"2026-08-25T08:03:08.532061Z\",\"shell.execute_reply\":\"2026-08-25T08:08:24.219328Z\"}}\n%run experimento_fase2.py\n","metadata":{"_uuid":"59ee9887-5e52-4b45-b3fd-20af139b28df","_cell_guid":"df405fba-b29c-4c5a-a8e6-5e802c6eae41","trusted":true,"collapsed":false,"jupyter":{"outputs_hidden":false}},"outputs":[],"execution_count":null}]}